  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addPostFrameCallback((_) {
      final face      = context.read<FaceScanController>();
      final lifestyle = context.read<LifestyleController>();
      context.read<RecommendationController>().rebuild(face, lifestyle);
    });
  }

  @override
